            while stack:
                x,y=stack.pop(); comp.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and a[nx][ny]==color:
                        seen.add((nx,ny)); stack.append((nx,ny))
            if len(comp)==1: singles.append(comp[0])
